select dept_name, case when location in ('London', 'Singapore') then 'priority' else 'other' end location_group, location, round((100 * sum(case when location = 'Berlin' then 1 else 0 end)) / count(*), 1) pct_berlin, sum(case when location = 'London' then budget else 0 end) london_budget from departments where budget is not null and location in ('New York', 'Tokyo') group by dept_name, location_group, location having pct_berlin >= 58;
